def unit(v):
    v = np.asarray(v, dtype=float)
    return v / np.linalg.norm(v)


def rotation(degrees):
    a = math.radians(degrees)
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])


def png(path, im):
    buf = BytesIO()
    im.save(buf, "PNG", compress_level=9)
    OUTPUTS[path] = buf.getvalue()


def write_json(path, value):
    OUTPUTS[path] = (json.dumps(value, indent=2, ensure_ascii=False) + "\n").encode()


@dataclass
class Face:
    xyz: np.ndarray
    uv: np.ndarray
    texture: Image.Image
    normal: np.ndarray
    unlit: bool = False


class Atlas:
    """One 64px atlas; face patches retain sixteen texels per node.

    Adjacent identical patches share UV space. One-pixel duplicated gutters
    prevent unrelated patches bleeding at their edges under texture filtering.
    """

    def __init__(self):
        self.image = Image.new("RGBA", (64, 64), (118, 78, 49, 255))
        self.used = np.zeros((64, 64), dtype=bool)
        self.cache = {}

    def patch(self, w, h, style):
        w, h = max(1, math.ceil(w - 1e-8)), max(1, math.ceil(h - 1e-8))
        key = (w, h, style)
        if key in self.cache:
            return self.cache[key]
        location = next(((x, y) for y in range(64 - h - 1)
                         for x in range(64 - w - 1)
                         if not self.used[y:y+h+2, x:x+w+2].any()), None)
        if location is None:
            raise ValueError("Atlas overflow")
        im = Image.new("RGBA", (w, h))
        d = ImageDraw.Draw(im)
        for y in range(h):
            for x in range(w):
                # Original, deliberately quiet horizontal wood grain. The
                # palette follows existing timber; no reference pixels copied.
                n = ((x // 4 + y * 3) % 5) - 2
                if style == "panel":
                    base, delta = (184, 143, 92), n
                elif style == "plain":
                    base, delta = (184, 143, 92), n
                    if y in (0, h - 1):
                        base = (152, 109, 66)
                elif style == "post":
                    # Uniform around the post and along its length: arbitrary
                    # stacked rotations introduce no grain rings at the join.
                    base, delta = (127, 90, 60), 0
                elif style == "frame":
                    base, delta = (130, 92, 55), n * 3
                    if y == 0:
                        base = (165, 124, 76)
                elif style == "roof":
                    base, delta = (118, 78, 49), n * 3
                    if x % 5 == 0:
                        base = (93, 64, 41)
                elif style == "back":
                    base, delta = (155, 112, 69), n * 3
                else:
                    base, delta = (127, 90, 60), n * 2
                d.point((x, y), tuple(v + delta for v in base) + (255,))
        px, py = location[0] + 1, location[1] + 1
        self.used[py-1:py+h+1, px-1:px+w+1] = True
        self.image.paste(im, (px, py))
        self.image.paste(im.crop((0, 0, w, 1)), (px, py - 1))
        self.image.paste(im.crop((0, h - 1, w, h)), (px, py + h))
        self.image.paste(im.crop((0, 0, 1, h)), (px - 1, py))
        self.image.paste(im.crop((w - 1, 0, w, h)), (px + w, py))
        for dx, dy in ((-1, -1), (w, -1), (-1, h), (w, h)):
            self.image.putpixel((px + dx, py + dy),
                                im.getpixel((0 if dx < 0 else w - 1,
                                             0 if dy < 0 else h - 1)))
        self.cache[key] = (px, py)
        return px, py


class Mesh:
    def __init__(self, name):
        self.name = name
        self.faces = []
        self.atlas = Atlas()

    def face(self, points, style="edge", outward=None):
        xyz = np.asarray(points, dtype=float)
        normal = unit(np.cross(xyz[1] - xyz[0], xyz[2] - xyz[0]))
        if outward is not None and np.dot(normal, outward) < 0:
            xyz = xyz[::-1]
            normal = -normal
        # Horizontal boards use horizontal grain. Vertical post faces use
        # their horizontal tangent, so grain axes stay stable at any yaw.
        if abs(normal[1]) < 0.99:
            right = unit(np.cross(normal, [0, 1, 0]))
            up = unit(np.cross(right, normal))
        else:
            right = unit(xyz[1] - xyz[0])
            up = unit(np.cross(right, normal))
        planar = np.column_stack((xyz @ right, -xyz @ up)) * 16
        planar -= planar.min(axis=0)
        w, h = planar.max(axis=0)
        px, py = self.atlas.patch(w, h, style)
        uv = (planar + [px, py]) / 64
        self.faces.append(Face(xyz, uv, self.atlas.image, normal))

    def box(self, bounds, styles=None):
        x0, y0, z0, x1, y1, z1 = bounds
        styles = styles or {}
        sides = [
            ("front", [(x0,y0,z0),(x0,y1,z0),(x1,y1,z0),(x1,y0,z0)]),
            ("back", [(x1,y0,z1),(x1,y1,z1),(x0,y1,z1),(x0,y0,z1)]),
            ("left", [(x0,y0,z1),(x0,y1,z1),(x0,y1,z0),(x0,y0,z0)]),
            ("right", [(x1,y0,z0),(x1,y1,z0),(x1,y1,z1),(x1,y0,z1)]),
            ("top", [(x0,y1,z0),(x0,y1,z1),(x1,y1,z1),(x1,y1,z0)]),
            ("bottom", [(x0,y0,z1),(x0,y0,z0),(x1,y0,z0),(x1,y0,z1)]),
        ]
        for side, pts in sides:
            self.face(pts, styles.get(side, styles.get("all", "edge")))

    def prism(self, outline, z0, z1, front="panel", back="back", edge="edge"):
        a = np.array([(x, y, z0) for x, y in outline])
        b = np.array([(x, y, z1) for x, y in outline])
        self.face(a, front, [0, 0, -1])
        self.face(b, back, [0, 0, 1])
        middle = (a.mean(axis=0) + b.mean(axis=0)) / 2
        for i in range(len(outline)):
            j = (i + 1) % len(outline)
            points = np.array([a[i], a[j], b[j], b[i]])
            self.face(points, edge, points.mean(axis=0) - middle)

    def post(self, low, high, cap_low=False, cap_high=False):
        radius = 0.0625
        ring = [(radius * math.cos(i * math.tau / 24),
                 radius * math.sin(i * math.tau / 24)) for i in range(24)]
        for i, (x, z) in enumerate(ring):
            xx, zz = ring[(i + 1) % 24]
            self.face([(x, low, z), (x, high, z), (xx, high, zz), (xx, low, zz)],
                      "post", [x + xx, 0, z + zz])
        if cap_low:
            self.face([(x, low, z) for x, z in ring], "post", [0, -1, 0])
        if cap_high:
            self.face([(x, high, z) for x, z in ring], "post", [0, 1, 0])

    def transform(self, degrees):
        matrix = rotation(degrees)
        for f in self.faces:
            f.xyz = f.xyz @ matrix.T
            f.normal = matrix @ f.normal

    def bounds(self):
        points = np.concatenate([f.xyz for f in self.faces])
        return np.concatenate((points.min(axis=0), points.max(axis=0))).round(7).tolist()

    def obj(self):
        vertices, normals, uvs, triangles = [], [], [], []
        vertex_ids = {}
        for face in self.faces:
            normal_id = len(normals) + 1
            normals.append(face.normal)
            corners = []
            for xyz, uv in zip(face.xyz, face.uv):
                key = tuple(np.round(xyz, 9))
                if key not in vertex_ids:
                    vertex_ids[key] = len(vertices) + 1
                    vertices.append(xyz)
                uvs.append((uv[0], 1 - uv[1]))
                corners.append(f"{vertex_ids[key]}/{len(uvs)}/{normal_id}")
            for i in range(1, len(corners) - 1):
                triangles.append(f"f {corners[0]} {corners[i]} {corners[i + 1]}")
        lines = ["# SPDX-License-Identifier: CC0-1.0", "# Original Grudgelands sign; node units.",
                 f"mtllib {self.name}.mtl", f"o {self.name}"]
        for prefix, rows in (("v", vertices), ("vt", uvs), ("vn", normals)):
            lines += [prefix + " " + " ".join(f"{n:.9f}" for n in row) for row in rows]
        lines += ["g wood", "usemtl wood", "s off"] + triangles
        return ("\n".join(lines) + "\n").encode(), len(vertices), len(triangles)


def text_area(center, width, height, lines, columns, back=False):
    return {"center": center, "width": width, "height": height,
            "normal": [0, 0, 1 if back else -1],
            "right": [-1 if back else 1, 0, 0], "up": [0, 1, 0],
            "lines": lines, "characters_per_line": columns,
            "surface_offset": 0.003}


def create(kind, variant, waypost_front=False):
    mesh = Mesh(f"{kind}_{variant}")
    selection = []
    if kind == "sign_standing":
        thick = 0.0625 if variant == "a" else 0.09375
        mesh.box([-thick, -0.5, -0.03125, thick, 0.4375, 0.09375], {"all": "frame"})
        if variant == "a":
            board = [-0.4375, -0.125, -0.09375, 0.4375, 0.5, -0.03125]
            mesh.box(board, {"front": "plain", "back": "back"})
            front_z = -0.09375
        else:
            board = [-0.46875, -0.125, -0.125, 0.46875, 0.5, -0.03125]
            mesh.box(board, {"front": "panel", "back": "back"})
            for box in [[-0.46875,-0.125,-0.15625,-0.40625,0.5,-0.125],
                        [0.40625,-0.125,-0.15625,0.46875,0.5,-0.125],
                        [-0.40625,-0.125,-0.15625,0.40625,-0.0625,-0.125],
                        [-0.40625,0.4375,-0.15625,0.40625,0.5,-0.125]]:
                mesh.box(box, {"all": "frame"})
            front_z = -0.125
        areas = [text_area([0, 0.1875, front_z - 0.003], 0.8125, 0.5, 4, 15)]
        selection = [[-thick, -0.5, -0.03125, thick, -0.125, 0.09375],
                     [board[0], board[1], front_z - (0.03125 if variant == "b" else 0),
                      board[3], board[4], board[5]]]
    elif kind == "waypost":
        low, high = (0.125, 0.375) if variant == "a" else (0.0625, 0.4375)
        if variant == "a":
            outline = [(-0.5,low),(0.3125,low),(0.5,0.25),(0.3125,high),(-0.5,high)]
        else:
            outline = [(-0.5,0.125),(-0.4375,low),(0.3125,low),(0.5,0.25),
                       (0.3125,high),(-0.4375,high),(-0.5,0.375)]
        # The plank passes through the post. The central post section is
        # omitted, so neither writing face is obstructed by the support.
        mesh.post(-0.5, low, cap_low=True)
        mesh.post(high, 0.5, cap_high=True)
        mesh.prism(outline, -0.0625, 0.0625,
                   front="panel" if variant == "a" else "plain",
                   back="panel" if variant == "a" else "plain")
        areas = [text_area([-0.09375, 0.25, -0.0655], 0.75, 0.14, 1, 14),
                 text_area([-0.09375, 0.25, 0.0655], 0.75, 0.14, 1, 14, True)]
        selection = [[-0.0625,-0.5,-0.0625,0.0625,0.5,0.0625],
                     [-0.5,low,-0.0625,0.5,high,0.0625]]
        if not waypost_front:
            mesh.transform(90)
            for area in areas:
                for key in ("center", "normal", "right", "up"):
                    values = np.round(rotation(90) @ area[key], 7)
                    values[np.abs(values) < 1e-7] = 0
                    area[key] = values.tolist()
            selection[1] = [-0.0625,low,-0.5,0.0625,high,0.5]
    else:
        for x in (-0.375, 1.375):
            mesh.box([x-0.0625,-0.5,0.0,x+0.0625,1.0,0.125], {"all": "frame"})
        mesh.box([-0.5,0,-0.0625,1.5,1,0], {"front": "panel", "back": "back"})
        for box in [[-0.5,0,-0.125,-0.375,1,-0.0625],
                    [1.375,0,-0.125,1.5,1,-0.0625],
                    [-0.375,0,-0.125,1.375,0.0625,-0.0625],
                    [-0.375,0.9375,-0.125,1.375,1,-0.0625]]:
            mesh.box(box, {"all": "frame"})
        if variant == "b":
            # Two sloped boards, ridge along X, with no lateral overhang
            # beyond the two reserved nodes. No roof crosses the text area.
            for sign in (-1, 1):
                z0, z1 = 0, sign * 0.25
                points = [(z0,1.125),(z1,1.0),(z1,1.0625),(z0,1.1875)]
                roof = Mesh("roof")
                roof.prism(points, -0.5, 1.5, "frame", "frame", "roof")
                # Temporary prism X is roof Z; temporary Z is roof X.
                for f in roof.faces:
                    xyz = f.xyz[:, [2, 1, 0]]
                    mesh.face(xyz, "roof", f.normal[[2, 1, 0]])
        areas = [text_area([0.5, 0.5, -0.0655], 1.75, 0.875, 7, 30)]
        selection = [[-0.4375,-0.5,0,-0.3125,0,0.125],
                     [1.3125,-0.5,0,1.4375,0,0.125],
                     [-0.5,0,-0.125,1.5,1,0.125]]
        if variant == "b":
            selection.append([-0.5,1,-0.25,1.5,1.1875,0.25])
    raw, vertices, triangles = mesh.obj()
    spec = {
        "schema": 1, "model": mesh.name + ".obj", "units": "nodes",
        "origin": "Centre of the placed node; ground at y = -0.5.",
        "front_normal": areas[0]["normal"],
        "texture_slots": [{"slot": 1, "group": "wood", "material": "wood",
                           "texture": mesh.name + ".png"}],
        "texture_size": [64, 64], "texels_per_node": 16,
        "inventory_image": mesh.name + "_inv.png", "vertices": vertices,
        "faces": triangles, "face_type": "triangles", "bounds": mesh.bounds(),
        "text_areas": areas,
        "preview_text": {"font_pixel_node_size": FONT_PIXEL, "glyph_height_px": 12,
                         "character_advance_px": CHAR_ADVANCE,
                         "line_advance_px": LINE_ADVANCE, "ink": "#2b1e14",
                         "lines": SAMPLES[kind], "scale_to_fit": False},
        "selection_box": {"type": "fixed", "fixed": selection},
        "collision_box": {"type": "fixed", "fixed": selection},
        "box_convention": "Unrotated model-local boxes; integration owns rotated selection and collision.",
        "suggested_walkable": False if kind != "notice_board" else True,
        "license": "CC0-1.0",
    }
    if kind == "waypost":
        spec["arrow_direction"] = [1, 0, 0] if waypost_front else [0, 0, -1]
        spec["stack"] = {"translation": [0, 1, 0], "post_axis": [0, 1, 0],
                         "post_radius": 0.0625, "post_sides": 24,
                         "post_bottom": -0.5, "post_top": 0.5,
                         "arrow_y_min": low, "arrow_y_max": high,
                         "vertical_clearance": 1 - (high - low),
                         "max_rotated_profile_difference": round(0.0625*(1-math.cos(math.pi/24)),9),
                         "note": "Flush end planes, identical post colour, no collars; sub-texel round faceting."}
    if kind == "notice_board":
        spec["origin"] = "Centre of the left node, as seen from the front (-Z); second node at +X."
        spec["occupied_nodes"] = [[0, 0, 0], [1, 0, 0]]
        spec["height_from_ground"] = mesh.bounds()[4] + 0.5
        spec["placement_clearance"] = "Upper board/roof rises above the base node; check headroom over both nodes."
    OUTPUTS[f"candidates/{mesh.name}.obj"] = raw
    OUTPUTS[f"candidates/{mesh.name}.mtl"] = (
        "# SPDX-License-Identifier: CC0-1.0\nnewmtl wood\nKa 1 1 1\nKd 1 1 1\n"
        f"Ks 0 0 0\nd 1\nillum 1\nmap_Kd {mesh.name}.png\n").encode()
    write_json(f"candidates/{mesh.name}.json", spec)
    png(f"candidates/{mesh.name}.png", mesh.atlas.image)
    png(f"preview/{mesh.name}.png", mesh.atlas.image)
    return mesh, spec


def letter_texture(lines, columns, rows, colour=INK):
    # Same bitmap pixel scale on every surface. The seven-pixel advance
    # leaves 0.735 node for 14 characters and 1.575 nodes for 30. Actual
    # glyph images keep their original size and alpha; no font smoothing.
    width = max(len(line) for line in lines) * CHAR_ADVANCE
    height = rows * LINE_ADVANCE
    im = Image.new("RGBA", (width, height))
    for row, line in enumerate(lines):
        assert len(line) <= columns, (line, columns)
        x = (width - len(line) * CHAR_ADVANCE) // 2
        for ch in line:
            box = CHARMAP[ch]["box"]
            glyph = FONT.crop(box)
            ink = Image.new("RGBA", glyph.size, colour)
            ink.putalpha(glyph.getchannel("A"))
            im.alpha_composite(ink, (x, row * LINE_ADVANCE))
            x += CHAR_ADVANCE
    return im


def text_faces(spec, lines=None):
    faces = []
    for area in spec["text_areas"]:
        im = letter_texture(lines or spec["preview_text"]["lines"],
                            area["characters_per_line"], area["lines"],
                            spec["preview_text"].get("ink", INK))
        center, right, up = [np.array(area[k]) for k in ("center", "right", "up")]
        width, height = im.width * FONT_PIXEL, im.height * FONT_PIXEL
        if width > area["width"] + 1e-8 or height > area["height"] + 1e-8:
            raise ValueError(f"Sample text exceeds {spec['model']} text area")
        corners = [center-right*width/2-up*height/2, center-right*width/2+up*height/2,
                   center+right*width/2+up*height/2, center+right*width/2-up*height/2]
        faces.append(Face(np.array(corners), np.array([[0,1],[0,0],[1,0],[1,1]]),
                          im, np.array(area["normal"]), True))
    return faces


def place(faces, offset=(0,0,0), yaw=0):
    matrix = rotation(yaw)
    return [Face(f.xyz @ matrix.T + offset, f.uv, f.texture, matrix @ f.normal,
                 f.unlit) for f in faces]


def render(faces, size=(420, 340), yaw=0, elevation=0, scale=230,
           target=(0,0,0), background=BG):
    """Orthographic, nearest-neighbour rasterizer with z-buffer and back culling."""
    theta, phi = math.radians(yaw), math.radians(elevation)
    toward = np.array([math.sin(theta)*math.cos(phi), math.sin(phi),
                       -math.cos(theta)*math.cos(phi)])
    right = np.array([math.cos(theta), 0, math.sin(theta)])
    up = np.cross(right, toward)
    basis = np.array([right, -up, toward]).T
    canvas = np.empty((size[1], size[0], 4), dtype=np.uint8)
    canvas[:] = background
    zbuf = np.full((size[1], size[0]), -np.inf)
    light = unit([-0.4, 0.9, -0.7])
    for face in faces:
        if np.dot(face.normal, toward) <= 1e-8:
            continue
        xyz = (face.xyz - np.array(target)) @ basis
        xyz[:, :2] = xyz[:, :2] * scale + np.array(size) / 2
        tex = np.asarray(face.texture)
        shade = 1 if face.unlit else 0.78 + 0.22 * max(0, np.dot(face.normal, light))
        for i in range(1, len(xyz)-1):
            ids = [0, i, i+1]
            tri, uv = xyz[ids], face.uv[ids]
            x0, y0 = np.maximum(0, np.floor(tri[:, :2].min(axis=0))).astype(int)
            x1, y1 = np.minimum(np.array(size)-1, np.ceil(tri[:, :2].max(axis=0))).astype(int)
            if x1 < x0 or y1 < y0:
                continue
            a, b, c = tri[:, :2]
            denom = (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
            if abs(denom) < 1e-10:
                continue
            yy, xx = np.mgrid[y0:y1+1, x0:x1+1]
            dx, dy = xx+0.5-a[0], yy+0.5-a[1]
            beta = (dx*(c[1]-a[1]) - dy*(c[0]-a[0])) / denom
            gamma = ((b[0]-a[0])*dy - (b[1]-a[1])*dx) / denom
            alpha = 1-beta-gamma
            depth = alpha*tri[0,2] + beta*tri[1,2] + gamma*tri[2,2]
            u = alpha*uv[0,0] + beta*uv[1,0] + gamma*uv[2,0]
            v = alpha*uv[0,1] + beta*uv[1,1] + gamma*uv[2,1]
            tx = np.clip((u*tex.shape[1]).astype(int), 0, tex.shape[1]-1)
            ty = np.clip((v*tex.shape[0]).astype(int), 0, tex.shape[0]-1)
            colour = tex[ty, tx].copy()
            colour[:, :, :3] = np.clip(colour[:, :, :3] * shade, 0, 255).astype(np.uint8)
            old_z = zbuf[y0:y1+1, x0:x1+1]
            keep = ((alpha >= -1e-8) & (beta >= -1e-8) & (gamma >= -1e-8)
                    & (depth > old_z + 1e-10) & (colour[:,:,3] > 0))
            canvas[y0:y1+1, x0:x1+1][keep] = colour[keep]
            old_z[keep] = depth[keep]
    return Image.fromarray(canvas)


def inventory(mesh, spec, yaw):
    # Rasterize the actual unlettered model directly on the 16px grid. Both
    # display sizes use this one icon; 32px is nearest-neighbour enlargement.
    bounds = spec["bounds"]
    target = (np.array(bounds[:3]) + bounds[3:]) / 2
    extent = max(np.array(bounds[3:]) - bounds[:3])
    return render(mesh.faces, (16,16), yaw, 8, 14/extent, target, (0,0,0,0))


def wall_candidates():
    textures = {}
    for material, palette in WALL_PALETTES.items():
        # Original pixels, drawn from scratch. Keep the nodebox tile layout:
        # front [1:15, 3:13], calm interior [1:15, 4:12], thin edges on row 15.
        im = Image.new("RGBA", (16, 16))
        d = ImageDraw.Draw(im)
        d.rectangle((0, 0, 15, 15), outline=palette["edge"])
        d.rectangle((0, 3, 15, 12), fill=palette["edge"])
        d.rectangle((1, 4, 14, 11), fill=palette["panel"])
        d.line((1, 3, 14, 3), fill=palette["rim_top"])
        d.line((1, 12, 14, 12), fill=palette["rim_bottom"])
        textures[material] = im
        for directory in ("candidates", "preview"):
            png(f"{directory}/sign_wall_{material}.png", im)
    return textures


def wall_mesh(texture):
    wall = Mesh("wall_sign")
    # Actual nodebox against +Z (wallmounted 4), before centring for display.
    # UVs include the engine's tile rotations for wallmounted -> facedir 8;
    # all four thin edges read row 15, not a stretched front-face patch.
    wall.box([-0.4375,-0.3125,0.4375,0.4375,0.3125,0.5])
    for f in wall.faces:
        f.texture = texture.copy()
        f.texture.putalpha(255)  # The runtime node uses opaque texture alpha.
        x, y, z = f.xyz.T
        if f.normal[2] < -0.9:
            uv = (x+0.5, 0.5-y)
        elif f.normal[2] > 0.9:
            uv = (x+0.5, y+0.5)
        elif f.normal[1] > 0.9:
            uv = (0.5-x, z+0.5)
        elif f.normal[1] < -0.9:
            uv = (x+0.5, z+0.5)
        elif f.normal[0] > 0.9:
            uv = (y+0.5, z+0.5)
        else:
            uv = (0.5-y, z+0.5)
        f.uv = np.column_stack(uv)
        f.xyz[:, 2] -= 0.46875
    return wall


def wall_spec():
    return {"model": "wall_sign", "text_areas": [
        text_area([0,0,-0.03425], 0.8125, 0.5, 4, 15)],
        "preview_text": {"lines": STANDING_TEXT, "ink": WALL_INK}}


def chest_reference():
    folder = ROOT / "mods/BASE/default/textures"
    chest = Mesh("chest_reference")
    chest.box([-0.5,-0.5,-0.5,0.5,0.5,0.5])
    for f in chest.faces:
        name = "front" if f.normal[2] < -0.9 else "top" if abs(f.normal[1]) > 0.9 else "side"
        f.texture = Image.open(folder / f"default_chest_{name}.png").convert("RGBA")
        f.uv = np.array([[0,1],[0,0],[1,0],[1,1]])
    return chest


def caption(im, text, xy, fill=(222,222,207,255), size=16):
    ImageDraw.Draw(im).text(xy, text, font=ImageFont.load_default(size=size), fill=fill)


def scene(package, variant, waypost_front, walls):
    wall, chest = wall_mesh(walls["wood"]), chest_reference()
    faces = place(chest.faces, (-2.9, 0, 0))
    faces += place(wall.faces + text_faces(wall_spec()), (-1.6,0.1875,0))
    for kind, x in (("sign_standing", -0.3), ("waypost", 1), ("notice_board", 2.45)):
        mesh, spec = package[f"{kind}_{variant}"]
        yaw = -90 if kind == "waypost" and not waypost_front else 0
        faces += place(mesh.faces + text_faces(spec), (x,0,0), yaw)
    im = render(faces, (1500,450), 0, 0, SCENE_SCALE, (0.55,0.35,0))
    d = ImageDraw.Draw(im)
    ground = int(450/2 + (0.35+0.5)*SCENE_SCALE)
    d.line((30,ground,1470,ground), fill=(107,112,101,255))
    for x in range(-4, 6):
        sx = int(750 + (x-0.55)*SCENE_SCALE)
        d.line((sx,ground,sx,ground+8), fill=(107,112,101,255))
    caption(im, "Shared scale: one grid interval = one node", (35,18), size=18)
    labels = [(-2.9,"Existing chest"),(-1.6,"New wall texture"),(-0.3,"Standing sign"),
              (1,"Waypost"),(2.95,"Notice board")]
    for x, label in labels:
        sx = 750 + (x-0.55)*SCENE_SCALE
        width = d.textbbox((0,0),label,font=ImageFont.load_default(size=15))[2]
        caption(im,label,(sx-width/2,ground+25),size=15)
    return im


def wall_comparison(package, walls):
    # Original, preview-only masonry. These small wall sections make the
    # attachment visible while preserving the scale of the family strips.
    masonry = Image.new("RGBA", (18, 18), (77, 83, 84, 255))
    d = ImageDraw.Draw(masonry)
    for row in range(3):
        for col in range(-1, 3):
            x, y = col*9+(row % 2)*4, row*6
            d.rectangle((x+1,y+1,x+8,y+5), fill=(98+row*2,104+row*2,103+row*2,255))
    backing = Mesh("preview_wall")
    backing.box([-0.5625,-0.5,0.03125,0.5625,0.625,0.1875])
    for f in backing.faces:
        f.texture = masonry
        f.uv = np.array([[0,1],[0,0],[1,0],[1,1]])
    faces, labels = [], []
    for x, material, old in ((-3,"wood",True),(-1.5,"wood",False),
                              (0,"iron",True),(1.5,"iron",False)):
        texture = (Image.open(HERE / f"inputs/wall_{material}_before.png").convert("RGBA")
                   if old else walls[material])
        faces += place(backing.faces, (x,0,0))
        faces += place(wall_mesh(texture).faces + text_faces(wall_spec()), (x,0.1875,0))
        labels.append((x, f"{material.title()} / {'old' if old else 'new'}"))
    mesh, spec = package["sign_standing_a"]
    faces += place(mesh.faces + text_faces(spec), (3,0,0))
    labels.append((3, "Standing A / picked"))
    im = render(faces, (1500,450), 0, 0, SCENE_SCALE, (0,0.35,0))
    d = ImageDraw.Draw(im)
    ground = int(225+(0.35+0.5)*SCENE_SCALE)
    d.line((35,ground,1465,ground), fill=(107,112,101,255))
    caption(im, "Same text, font and ink #2B1E14 on every board / 169 px per node", (35,18), size=18)
    for x, label in labels:
        width = d.textbbox((0,0),label,font=ImageFont.load_default(size=16))[2]
        caption(im, label, (750+x*SCENE_SCALE-width/2,ground+25))
    return im


